SET XACT_ABORT ON;

BEGIN TRY
    BEGIN TRANSACTION;

    TRUNCATE TABLE [DWH].[SalesInfoForecast];

    INSERT INTO [DWH].[SalesInfoForecast]
        ([CustomerID], [Month], [ProductID], [Total], [Year])
    EXEC sys.sp_execute_external_script
        @language = N'Python',

        @input_data_1 = N'
            SELECT [CustomerID], [Month], [ProductID], [Total], [Year]
            FROM [TRN].[SalesInfo];
        ',

        @script = N'
import pandas as pd
import math

# Source data
input_df = InputDataSet.copy()

# Output schema aligned with the target table
output_types = {
    "CustomerID": "object",
    "Month": "int32",
    "ProductID": "int32",
    "Total": "float64",
    "Year": "int32"
}

FORECAST_MONTHS = 6
HISTORY_MONTHS = 12

rows = []

if not input_df.empty:
    required_columns = list(output_types)

    missing_columns = [
        column for column in required_columns
        if column not in input_df.columns
    ]
    if missing_columns:
        raise ValueError(
            "Missing input columns: " + ", ".join(missing_columns)
        )

    if input_df[required_columns].isna().any().any():
        raise ValueError("Input columns must not contain NULL values.")

    # Normalize and validate numeric columns.
    for column in ["Month", "ProductID", "Total", "Year"]:
        input_df[column] = pd.to_numeric(
            input_df[column], errors="raise"
        )

        if not input_df[column].map(math.isfinite).all():
            raise ValueError(
                column + " contains missing or non-finite values."
            )

    for column in ["Month", "ProductID", "Year"]:
        if not (input_df[column] % 1 == 0).all():
            raise ValueError(column + " must contain whole numbers.")

        if not input_df[column].between(
            -2147483648, 2147483647
        ).all():
            raise ValueError(column + " is outside the SQL int range.")

        input_df[column] = input_df[column].astype("int32")

    if not input_df["Month"].between(1, 12).all():
        raise ValueError("Month must be between 1 and 12.")

    input_df["CustomerID"] = input_df["CustomerID"].astype(str)
    input_df["Total"] = input_df["Total"].astype("float64")

    # Internal date used for monthly aggregation and year rollover.
    input_df["Date"] = pd.to_datetime(
        {
            "year": input_df["Year"],
            "month": input_df["Month"],
            "day": 1
        },
        errors="raise"
    )

    # Aggregate any duplicate customer/product/month records.
    monthly_sales = (
        input_df.groupby(
            ["CustomerID", "ProductID", "Date"],
            as_index=False
        )["Total"]
        .sum()
    )

    # All combinations share the same forecast period.
    last_month = monthly_sales["Date"].max()

    forecast_dates = pd.date_range(
        start=last_month + pd.offsets.MonthBegin(1),
        periods=FORECAST_MONTHS,
        freq="MS"
    )

    for (customer_id, product_id), group in monthly_sales.groupby(
        ["CustomerID", "ProductID"]
    ):
        # Use up to 12 months through the common historical cutoff.
        # Do not include months before the first observed sale.
        history_start = max(
            group["Date"].min(),
            last_month - pd.DateOffset(months=HISTORY_MONTHS - 1)
        )

        history_dates = pd.date_range(
            start=history_start,
            end=last_month,
            freq="MS"
        )

        # Missing months within this period count as zero sales.
        sales = (
            group.set_index("Date")["Total"]
            .reindex(history_dates, fill_value=0.0)
            .astype("float64")
        )

        values = sales.tolist()
        count = len(values)

        mean_sales = sum(values) / count
        mean_index = (count - 1) / 2.0
        slope = 0.0

        # Fit a least-squares linear trend.
        # For fewer than three months, retain a flat average.
        if count >= 3:
            numerator = sum(
                (index - mean_index) * (total - mean_sales)
                for index, total in enumerate(values)
            )
            denominator = sum(
                (index - mean_index) ** 2
                for index in range(count)
            )
            slope = numerator / denominator

        for step, forecast_date in enumerate(forecast_dates):
            future_index = count + step

            forecast_total = (
                mean_sales + slope * (future_index - mean_index)
            )

            if not math.isfinite(forecast_total):
                raise ValueError(
                    "Forecast produced a non-finite value."
                )

            rows.append({
                "CustomerID": customer_id,
                "Month": forecast_date.month,
                "ProductID": product_id,
                "Total": max(0.0, float(forecast_total)),
                "Year": forecast_date.year
            })

# Column order must match INSERT ... EXEC.
# An empty source produces an empty result with the correct schema.
OutputDataSet = pd.DataFrame(
    rows,
    columns=list(output_types)
).astype(output_types)
';

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0
        ROLLBACK TRANSACTION;

    THROW;
END CATCH;
